INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','unreal-subjunctive','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"unreal-subjunctive","title":"Unreal time and the subjunctive","level":"C1","order":65,"summary":"Recognise formal recommendations, imagined situations and expressions whose past form refers to the present.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The mandative subjunctive","Negative subjunctives","Would rather and it is time","As if and hypothetical were"],"rules":[{"title":"The mandative subjunctive","explanation":"After a demand, recommendation or requirement, formal English can use a that-clause with the **base verb for every subject**. Be remains be. This pattern is especially common in American formal usage; British English also often uses should + base.","pattern":"They requested that she **be** present.","commonMistakes":["She be in a subjunctive clause is not an agreement error. The clause expresses a requirement rather than reporting a fact."],"examples":["Use the formal mandative subjunctive: “They recommend that she **prepare** the visitor guide today.”","Use the formal mandative subjunctive: “They recommend that she **restore** the old portrait today.”"],"skill":"form"},{"title":"Negative subjunctives","explanation":"In a mandative subjunctive, **not** normally comes directly before the base verb without do-support. The reporting verb may be past while the recommended action is later. The base verb does not backshift in the usual way.","pattern":"They insisted that he **not leave**.","commonMistakes":["The pattern differs from ordinary factual He does not leave. Read the demand or recommendation meaning first."],"examples":["Use a negative mandative subjunctive: “They insist that she **not prepare** the visitor guide without permission.”","Use a negative mandative subjunctive: “They insist that she **not restore** the old portrait without permission.”"],"skill":"meaning"},{"title":"Would rather and it is time","explanation":"Would rather + base verb expresses a preference about one’s own action. Would rather + subject + past form can express a preference about another person now or in the future. It is time + subject + past form says an action is overdue or due now.","pattern":"I’d rather **stay**. / I’d rather you **stayed**. / It’s time we **left**.","commonMistakes":["The past form in It’s time we left need not refer to a past departure."],"examples":["“I would rather **prepare** the visitor guide tomorrow.”","“I would rather **restore** the old portrait tomorrow.”"],"skill":"contrast"},{"title":"As if and hypothetical were","explanation":"As if or as though can compare a situation with an imagined one. A backshifted form can show that the speaker views it as unreal or doubtful. Were is common in formal hypothetical be clauses. Ordinary tenses remain possible when the comparison may be true.","pattern":"He speaks as if he **knew** everything.","commonMistakes":["As if does not automatically force unreal past; context can support an ordinary factual interpretation."],"examples":["The task is due now. Use the “it is time” past-form pattern: “It is time we **prepared** the visitor guide.”","The task is due now. Use the “it is time” past-form pattern: “It is time we **restored** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal","dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"252f4b5c-5d36-5725-ae1f-99c1e8d42730","topicSlug":"unreal-subjunctive","level":"C1","prompt":"Use the formal mandative subjunctive: “They recommend that she ____ the visitor guide today.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepare"},{"id":"C","text":"prepares"},{"id":"D","text":"prepared"}],"answerId":"B","hint":"The clause expresses a **recommendation**, and the requested form is the **subjunctive**.","explanation":"The requested subjunctive uses base **prepare**, without third-person -s.","keywords":["mandative-base"],"skill":"mandative-base","contextKey":"unreal-subjunctive-1","fingerprint":"e196f2397699a249dc7f3595a0a2a4315389ce3f3a167bd17173d0e7cbbb53d1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The clause expresses a **recommendation**, and the requested form is the **subjunctive**.","The requested subjunctive uses base **prepare**, without third-person -s.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A finite that-clause in this pattern does not use a to-infinitive.","B":"The requested subjunctive uses base **prepare**, without third-person -s.","C":"This is ordinary indicative agreement, not the explicitly requested subjunctive form.","D":"The subjunctive here uses a base form, not past tense."}}},{"id":"ad5145b9-58a2-522c-aed0-7f0c3c79c760","topicSlug":"unreal-subjunctive","level":"C1","prompt":"Use a negative mandative subjunctive: “They insist that she ____ the visitor guide without permission.”","choices":[{"id":"A","text":"not prepare"},{"id":"B","text":"does not prepare"},{"id":"C","text":"not prepares"},{"id":"D","text":"not to prepare"}],"answerId":"A","hint":"A mandative negative places **not directly before the base verb**.","explanation":"The negative subjunctive is **not + base prepare**, without does.","keywords":["negative-subjunctive"],"skill":"negative-subjunctive","contextKey":"unreal-subjunctive-1","fingerprint":"940827d4e14483a3dc319def59c78a461f0a0df4e1ab4502e3096c527853d9aa","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A mandative negative places **not directly before the base verb**.","The negative subjunctive is **not + base prepare**, without does.","Choose **not prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The negative subjunctive is **not + base prepare**, without does.","B":"This is indicative do-support, not the requested negative subjunctive.","C":"The subjunctive base form does not carry third-person -s.","D":"Not to is an infinitive, not this finite subjunctive clause."}}},{"id":"0a4e5d14-646a-5438-a261-6d932329224a","topicSlug":"unreal-subjunctive","level":"C1","prompt":"“I would rather ____ the visitor guide tomorrow.”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepare"},{"id":"D","text":"prepared"}],"answerId":"C","hint":"There is no new subject after rather, so use the **bare infinitive**.","explanation":"For the speaker’s own preference, **would rather** takes base **prepare**.","keywords":["rather-own-action"],"skill":"rather-own-action","contextKey":"unreal-subjunctive-1","fingerprint":"c42d95bd163afa4ab8a7418d5eaa754c89d9cd19dae1015daa93f30533fc1b5f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["There is no new subject after rather, so use the **bare infinitive**.","For the speaker’s own preference, **would rather** takes base **prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The direct complement is a base verb, not -ing.","B":"Would rather takes an infinitive without to.","C":"For the speaker’s own preference, **would rather** takes base **prepare**.","D":"A past form belongs in some different-subject preference clauses, not directly after would rather here."}}},{"id":"3343219f-fec5-55da-a91e-e09ade056221","topicSlug":"unreal-subjunctive","level":"C1","prompt":"The task is due now. Use the “it is time” past-form pattern: “It is time we ____ the visitor guide.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepared"},{"id":"C","text":"will prepare"},{"id":"D","text":"preparing"}],"answerId":"B","hint":"The past form expresses that the action is **due now**, not that it already happened.","explanation":"The pattern **it is time + subject + past form** uses **prepared** for an action due now.","keywords":["time-unreal-past"],"skill":"time-unreal-past","contextKey":"unreal-subjunctive-1","fingerprint":"5e39dc1bbf7e432687624c13938e0e7fbe5faaf7aa255f22fea7dc84415c6633","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past form expresses that the action is **due now**, not that it already happened.","The pattern **it is time + subject + past form** uses **prepared** for an action due now.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After the stated subject we, this pattern needs a finite past form.","B":"The pattern **it is time + subject + past form** uses **prepared** for an action due now.","C":"The requested it-is-time construction uses a past form, not will.","D":"An -ing form alone does not form the finite clause."}}},{"id":"467d57a7-ce06-5968-aaef-506a3dd9d3cc","topicSlug":"unreal-subjunctive","level":"C1","prompt":"Use the formal mandative subjunctive: “They recommend that she ____ the old portrait today.”","choices":[{"id":"A","text":"restored"},{"id":"B","text":"to restore"},{"id":"C","text":"restore"},{"id":"D","text":"restores"}],"answerId":"C","hint":"The clause expresses a **recommendation**, and the requested form is the **subjunctive**.","explanation":"The requested subjunctive uses base **restore**, without third-person -s.","keywords":["mandative-base"],"skill":"mandative-base","contextKey":"unreal-subjunctive-2","fingerprint":"45f3aba7e0c936258f26d1e0fc133d06ad37b2db88c4545d9ef7b243b9ce4404","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The clause expresses a **recommendation**, and the requested form is the **subjunctive**.","The requested subjunctive uses base **restore**, without third-person -s.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The subjunctive here uses a base form, not past tense.","B":"A finite that-clause in this pattern does not use a to-infinitive.","C":"The requested subjunctive uses base **restore**, without third-person -s.","D":"This is ordinary indicative agreement, not the explicitly requested subjunctive form."}}},{"id":"aec3dcfc-c9b5-5d78-a310-9650979bad16","topicSlug":"unreal-subjunctive","level":"C1","prompt":"Use a negative mandative subjunctive: “They insist that she ____ the old portrait without permission.”","choices":[{"id":"A","text":"not restore"},{"id":"B","text":"does not restore"},{"id":"C","text":"not restores"},{"id":"D","text":"not to restore"}],"answerId":"A","hint":"A mandative negative places **not directly before the base verb**.","explanation":"The negative subjunctive is **not + base restore**, without does.","keywords":["negative-subjunctive"],"skill":"negative-subjunctive","contextKey":"unreal-subjunctive-2","fingerprint":"5d646e1a51ce8e3554018a1c8e7b5d10d6adce820e5a82fa7857e28a6760e3c0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-unreal"],"version":"